    title: o.title,
    summary: o.summary || '',
    cwd: o.cwd,
    pinned: Boolean(o.pinned),
    createdAt: o.createdAt,
    updatedAt: o.updatedAt,
    messageCount: Number.isFinite(o.messageCount) ? o.messageCount : (o.messages?.length || 0),
