    if (temp !== undefined) b.temperature = temp;
    applyProviderReasoningEffort(b, provider, 'chat');
    const loadedTools = toolLoading.current();
    if (withTools && loadedTools.length) { b.tools = loadedTools; b.tool_choice = 'auto'; }
